            reverseWithGateways(
                lookupAddress,
                coinType,
                batchGatewayProvider.gateways()
            );
    }

    struct ReverseArgs {
        bytes lookupAddress; // parsed input address
        uint256 coinType; // parsed coinType
        string[] gateways; // supplied gateways
        address resolver; // valid reverse resolver
